const CORE_JS = "function clamp(value, min, max) {\n  return Math.max(min, Math.min(max, value));\n}\n\nfunction projectBar(bar, nowMs = Date.now()) {\n  if (!bar) return null;\n  const current = Number(bar.current || 0);\n  const maximum = Number(bar.maximum || 0);\n  const increment = Number(bar.increment || 0);\n  const interval = Number(bar.interval || 0);\n  const tickTimeMs = Number(bar.tick_time || 0) * 1000;\n  const fullTimeMs = Number(bar.full_time || 0) * 1000;\n\n  if (maximum <= 0) return {...bar, projected: current, percent: 0, capMs: null};\n  if (current >= maximum) return {...bar, projected: maximum, percent: 100, capMs: nowMs};\n\n  let projected = current;\n  if (interval > 0 && increment > 0 && tickTimeMs > 0 && nowMs >= tickTimeMs) {\n    const ticks = 1 + Math.floor((nowMs - tickTimeMs) / (interval * 1000));\n    projected = clamp(current + ticks * increment, current, maximum);\n  } else if (interval > 0 && increment > 0 && tickTimeMs <= 0 && fullTimeMs > nowMs) {\n    const remainingTicks = Math.ceil((fullTimeMs - nowMs) / (interval * 1000));\n    projected = clamp(maximum - remainingTicks * increment, current, maximum);\n  }\n\n  return {\n    ...bar,\n    projected,\n    percent: clamp((projected / maximum) * 100, 0, 100),\n    capMs: fullTimeMs > 0 ? fullTimeMs : null,\n  };\n}\n\nfunction formatDuration(seconds) {\n  const s = Math.max(0, Math.floor(Number(seconds) || 0));\n  if (s === 0) return 'READY';\n  const h = Math.floor(s / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  const sec = s % 60;\n  if (h > 0) return `${h}h ${m}m`;\n  if (m > 0) return `${m}m ${sec}s`;\n  return `${sec}s`;\n}\n\nfunction timeUntil(ms, nowMs = Date.now()) {\n  if (!ms) return 'UNKNOWN';\n  return formatDuration(Math.max(0, Math.ceil((ms - nowMs) / 1000)));\n}\n\nfunction recommend(snapshot, nowMs = Date.now()) {\n  const energy = projectBar(snapshot.energy, nowMs);\n  const nerve = projectBar(snapshot.nerve, nowMs);\n  const elapsed = Math.max(0, Math.floor((nowMs - Number(snapshot.fetchedAt || nowMs)) / 1000));\n  const drug = Math.max(0, Number(snapshot.cooldowns?.drug || 0) - elapsed);\n\n  if (nerve && nerve.percent >= 90) return {title: 'SPEND NERVE', detail: 'Your nerve is close to capping. Use it before natural regeneration is wasted.'};\n  if (energy && energy.percent >= 90) return {title: 'SPEND ENERGY', detail: 'Your energy is close to capping. Train or use it before natural regeneration is wasted.'};\n  if (drug === 0) return {title: 'DRUG READY', detail: 'Your drug cooldown is clear. Check whether using your planned drug fits your training strategy.'};\n  if (energy && energy.percent >= 60) return {title: 'PLAN TRAINING', detail: 'You have a healthy energy bar. Consider your next gym session before it creeps toward cap.'};\n  return {title: 'REGENERATING', detail: 'Nothing urgent right now. Let your bars regenerate and TornPulse will keep watch.'};\n}\n\nmodule.exports = {clamp, projectBar, formatDuration, timeUntil, recommend};\n";
const TORN_API_JS = "const BASE = 'https://api.torn.com/v2';\nconst TIMEOUT_MS = 12000;\n\nasync function getJson(path, key) {\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);\n  const joiner = path.includes('?') ? '&' : '?';\n  try {\n    const response = await fetch(`${BASE}${path}${joiner}comment=TornPulse`, {\n      headers: {Authorization: `ApiKey ${key}`, Accept: 'application/json'},\n      signal: controller.signal,\n    });\n    const json = await response.json().catch(() => null);\n    if (!response.ok || json?.error) {\n      const msg = json?.error?.error || json?.error?.message || `Torn API error (${response.status})`;\n      throw new Error(msg);\n    }\n    return json;\n  } catch (err) {\n    if (err?.name === 'AbortError') throw new Error('Torn API timed out. Check your connection and try again.');\n    throw err;\n  } finally {\n    clearTimeout(timer);\n  }\n}\n\nfunction normalizeBar(raw, nowUnix = Math.floor(Date.now() / 1000)) {\n  if (!raw) throw new Error('Missing Torn bar data.');\n  const current = Number(raw.current);\n  const maximum = Number(raw.maximum);\n  const increment = Number(raw.increment || 0);\n  const interval = Number(raw.interval || 0);\n  const fullSeconds = Math.max(0, Number(raw.full_time || 0));\n  const tickSeconds = Math.max(0, Number(raw.tick_time || 0));\n  if (!Number.isFinite(current) || !Number.isFinite(maximum) || maximum <= 0) throw new Error('Invalid Torn bar data.');\n  return {\n    ...raw,\n    current,\n    maximum,\n    increment,\n    interval,\n    api_full_time_seconds: fullSeconds,\n    api_tick_time_seconds: tickSeconds,\n    full_time: fullSeconds > 0 ? nowUnix + fullSeconds : (current >= maximum ? nowUnix : 0),\n    tick_time: tickSeconds > 0 ? nowUnix + tickSeconds : 0,\n  };\n}\n\nfunction normalizeStatus(raw) {\n  if (!raw) return {state:'Unknown', description:'Status unavailable', details:null, until:null, color:null};\n  return {\n    state: String(raw.state || 'Unknown'),\n    description: String(raw.description || raw.state || 'Unknown'),\n    details: raw.details == null ? null : String(raw.details),\n    until: raw.until == null ? null : Number(raw.until),\n    color: raw.color == null ? null : String(raw.color),\n  };\n}\n\nfunction validateBars(payload) {\n  const energyRaw = payload?.bars?.energy;\n  const nerveRaw = payload?.bars?.nerve;\n  const lifeRaw = payload?.bars?.life;\n  const happyRaw = payload?.bars?.happy;\n  if (!energyRaw || !nerveRaw || !lifeRaw || !happyRaw) throw new Error('Unexpected Torn bars response.');\n  return {energy: normalizeBar(energyRaw), nerve: normalizeBar(nerveRaw), life: normalizeBar(lifeRaw), happy: normalizeBar(happyRaw)};\n}\n\nasync function fetchLatestIncomingAttack(key) {\n  try {\n    const payload = await getJson('/user/attacks?filters=incoming&sort=DESC&limit=1', key);\n    const attack = Array.isArray(payload?.attacks) ? payload.attacks[0] : null;\n    if (!attack) return {attackAccess:true, lastIncomingAttack:null};\n    return {\n      attackAccess:true,\n      lastIncomingAttack:{\n        id: attack.id,\n        started: Number(attack.started || 0),\n        ended: Number(attack.ended || 0),\n        result: String(attack.result || 'Unknown'),\n        is_stealthed: Boolean(attack.is_stealthed),\n        attacker: attack.attacker ? {id:attack.attacker.id, name:String(attack.attacker.name || 'Unknown')} : null,\n      },\n    };\n  } catch (_) {\n    return {attackAccess:false, lastIncomingAttack:null};\n  }\n}\n\nasync function fetchSnapshot(key) {\n  const [barsPayload, cooldownPayload, basicPayload, attackInfo] = await Promise.all([\n    getJson('/user/bars', key),\n    getJson('/user/cooldowns', key),\n    getJson('/user/basic', key),\n    fetchLatestIncomingAttack(key),\n  ]);\n  const {energy, nerve, life, happy} = validateBars(barsPayload);\n  const cooldowns = cooldownPayload?.cooldowns;\n  if (!cooldowns || !['drug', 'medical', 'booster'].every(k => Number.isFinite(cooldowns[k]))) throw new Error('Unexpected Torn cooldown response.');\n  const profile = basicPayload?.profile || {};\n  return {\n    energy,\n    nerve,\n    life,\n    happy,\n    cooldowns,\n    profile:{id:profile.id ?? null, name:profile.name ?? null},\n    status:normalizeStatus(profile.status),\n    attackAccess:attackInfo.attackAccess,\n    lastIncomingAttack:attackInfo.lastIncomingAttack,\n    fetchedAt:Date.now(),\n    demo:false,\n  };\n}\n\nmodule.exports = {fetchSnapshot, normalizeBar, normalizeStatus};\n";
const OVERLAY_MODULE_KT = "package com.comfortableai.torncopilot\n\nimport android.content.Context\nimport android.app.Dialog\nimport android.content.Intent\nimport android.graphics.Bitmap\nimport android.graphics.Canvas\nimport android.graphics.Color\nimport android.graphics.drawable.ColorDrawable\nimport android.net.Uri\nimport android.os.Build\nimport android.util.Base64\nimport android.view.Gravity\nimport android.view.ViewGroup\nimport android.webkit.CookieManager\nimport android.webkit.WebChromeClient\nimport android.webkit.WebView\nimport android.webkit.WebViewClient\nimport android.widget.Button\nimport android.widget.LinearLayout\nimport android.widget.TextView\nimport java.io.ByteArrayOutputStream\nimport android.provider.Settings\nimport androidx.core.content.ContextCompat\nimport com.facebook.react.bridge.Promise\nimport com.facebook.react.bridge.ReactApplicationContext\nimport com.facebook.react.bridge.ReactContextBaseJavaModule\nimport com.facebook.react.bridge.ReactMethod\n\nclass ComfortableOverlayModule(private val appContext: ReactApplicationContext) : ReactContextBaseJavaModule(appContext) {\n  override fun getName(): String = \"ComfortableOverlay\"\n\n  @ReactMethod\n  fun hasPermission(promise: Promise) {\n    promise.resolve(Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext))\n  }\n\n  @ReactMethod\n  fun requestPermission(promise: Promise) {\n    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext)) {\n      promise.resolve(true)\n      return\n    }\n    try {\n      val intent = Intent(\n        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,\n        Uri.parse(\"package:${appContext.packageName}\")\n      ).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n      appContext.startActivity(intent)\n      promise.resolve(false)\n    } catch (e: Exception) {\n      promise.reject(\"OVERLAY_SETTINGS\", \"Unable to open Android overlay settings.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun startHud(apiKey: String, promise: Promise) {\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M && !Settings.canDrawOverlays(appContext)) {\n      promise.reject(\"OVERLAY_PERMISSION\", \"Display over other apps permission is required.\")\n      return\n    }\n    if (apiKey.isBlank()) {\n      promise.reject(\"API_KEY\", \"A Torn API key is required.\")\n      return\n    }\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_START\n        putExtra(ComfortableOverlayService.EXTRA_API_KEY, apiKey)\n      }\n      ContextCompat.startForegroundService(appContext, intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_START\", \"Unable to start TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun stopHud(promise: Promise) {\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_STOP\n      }\n      appContext.startService(intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_STOP\", \"Unable to stop TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun setHudPreferences(attackAlerts: Boolean, hudPreset: String, promise: Promise) {\n    try {\n      val preset = when (hudPreset.lowercase()) {\n        \"compact\" -> \"compact\"\n        \"large\" -> \"large\"\n        else -> \"standard\"\n      }\n      appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .putBoolean(\"attack_alerts\", attackAlerts)\n        .putString(\"hud_preset\", preset)\n        .apply()\n      if (ComfortableOverlayService.isRunning) {\n        appContext.startService(Intent(appContext, ComfortableOverlayService::class.java).apply {\n          action = ComfortableOverlayService.ACTION_UPDATE_PREFS\n        })\n      }\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_PREFS\", \"Unable to update TornPulse HUD preferences.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun resetHudPosition(promise: Promise) {\n    try {\n      appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .remove(\"x\")\n        .remove(\"y\")\n        .putBoolean(\"locked\", false)\n        .apply()\n      if (ComfortableOverlayService.isRunning) {\n        appContext.startService(Intent(appContext, ComfortableOverlayService::class.java).apply {\n          action = ComfortableOverlayService.ACTION_RESET_POSITION\n        })\n      }\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_RESET\", \"Unable to reset TornPulse HUD position.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun getAppIcon(promise: Promise) {\n    try {\n      val drawable = appContext.applicationInfo.loadIcon(appContext.packageManager)\n      val width = if (drawable.intrinsicWidth > 0) drawable.intrinsicWidth else 192\n      val height = if (drawable.intrinsicHeight > 0) drawable.intrinsicHeight else 192\n      val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\n      val canvas = Canvas(bitmap)\n      drawable.setBounds(0, 0, canvas.width, canvas.height)\n      drawable.draw(canvas)\n      val output = ByteArrayOutputStream()\n      bitmap.compress(Bitmap.CompressFormat.PNG, 100, output)\n      val encoded = Base64.encodeToString(output.toByteArray(), Base64.NO_WRAP)\n      promise.resolve(\"data:image/png;base64,$encoded\")\n    } catch (e: Exception) {\n      promise.reject(\"APP_ICON\", \"Unable to load TornPulse app icon.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun setHostVisible(visible: Boolean, promise: Promise) {\n    if (!ComfortableOverlayService.isRunning) {\n      promise.resolve(false)\n      return\n    }\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_HOST_VISIBILITY\n        putExtra(ComfortableOverlayService.EXTRA_HOST_VISIBLE, visible)\n      }\n      appContext.startService(intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_VISIBILITY\", \"Unable to update TornPulse HUD visibility.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun openTornApp(url: String, promise: Promise) {\n    try {\n      val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {\n        setPackage(\"com.ionicframework.tornv2301860\")\n        addCategory(Intent.CATEGORY_BROWSABLE)\n        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n      }\n      appContext.startActivity(intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"TORN_APP_UNAVAILABLE\", \"Official Torn app is not installed or could not open this link.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun openAttackBrowser(url: String, promise: Promise) {\n    val activity = appContext.currentActivity\n    if (activity == null) {\n      promise.reject(\"NO_ACTIVITY\", \"TornPulse could not open the in-app Torn browser.\")\n      return\n    }\n    activity.runOnUiThread {\n      try {\n        val cookies = CookieManager.getInstance()\n        cookies.setAcceptCookie(true)\n\n        val dialog = Dialog(activity, android.R.style.Theme_Black_NoTitleBar_Fullscreen)\n        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.BLACK))\n\n        val root = LinearLayout(activity).apply {\n          orientation = LinearLayout.VERTICAL\n          setBackgroundColor(Color.rgb(5, 6, 8))\n        }\n\n        val web = WebView(activity).apply {\n          setBackgroundColor(Color.BLACK)\n          settings.javaScriptEnabled = true\n          settings.domStorageEnabled = true\n          settings.databaseEnabled = true\n          settings.loadsImagesAutomatically = true\n          settings.useWideViewPort = true\n          settings.loadWithOverviewMode = false\n          settings.setSupportZoom(false)\n          webViewClient = WebViewClient()\n          webChromeClient = WebChromeClient()\n        }\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {\n          cookies.setAcceptThirdPartyCookies(web, true)\n        }\n\n        val top = LinearLayout(activity).apply {\n          orientation = LinearLayout.HORIZONTAL\n          gravity = Gravity.CENTER_VERTICAL\n          setPadding(18, 10, 10, 10)\n          setBackgroundColor(Color.rgb(13, 15, 18))\n        }\n        val title = TextView(activity).apply {\n          text = \"TORNPULSE • TORN\"\n          setTextColor(Color.rgb(242, 244, 246))\n          textSize = 14f\n          setTypeface(typeface, android.graphics.Typeface.BOLD)\n        }\n        val spacer = android.view.View(activity)\n        val back = Button(activity).apply {\n          text = \"BACK\"\n          setOnClickListener {\n            if (web.canGoBack()) web.goBack() else dialog.dismiss()\n          }\n        }\n        val close = Button(activity).apply {\n          text = \"CLOSE\"\n          setOnClickListener { dialog.dismiss() }\n        }\n        top.addView(title, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n        top.addView(spacer, LinearLayout.LayoutParams(0, 1, 1f))\n        top.addView(back, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n        top.addView(close, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n\n        root.addView(top, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n        root.addView(web, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 0, 1f))\n        dialog.setContentView(root, ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT))\n        dialog.setOnDismissListener {\n          cookies.flush()\n          web.stopLoading()\n          web.destroy()\n        }\n        dialog.show()\n        web.loadUrl(url)\n        promise.resolve(true)\n      } catch (e: Exception) {\n        promise.reject(\"ATTACK_BROWSER\", \"Unable to open TornPulse's in-app Torn browser.\", e)\n      }\n    }\n  }\n\n  @ReactMethod\n  fun openExternalUrl(url: String, promise: Promise) {\n    val uri = Uri.parse(url)\n    val browserPackages = listOf(\n      \"com.sec.android.app.sbrowser\",\n      \"com.android.chrome\",\n      \"com.google.android.apps.chrome\",\n      \"org.mozilla.firefox\",\n      \"com.brave.browser\",\n      \"com.microsoft.emmx\",\n      \"com.opera.browser\",\n      \"com.opera.gx\",\n      \"com.vivaldi.browser\",\n      \"com.duckduckgo.mobile.android\"\n    )\n    var lastError: Exception? = null\n    for (packageName in browserPackages) {\n      try {\n        val intent = Intent(Intent.ACTION_VIEW, uri).apply {\n          setPackage(packageName)\n          addCategory(Intent.CATEGORY_BROWSABLE)\n          addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n        }\n        appContext.startActivity(intent)\n        promise.resolve(packageName)\n        return\n      } catch (e: Exception) {\n        lastError = e\n      }\n    }\n    promise.reject(\"NO_EXTERNAL_BROWSER\", \"No supported external browser could open this Torn link.\", lastError)\n  }\n\n  @ReactMethod\n  fun isRunning(promise: Promise) {\n    promise.resolve(ComfortableOverlayService.isRunning)\n  }\n}\n";
const OVERLAY_PACKAGE_KT = "package com.comfortableai.torncopilot\n\nimport com.facebook.react.ReactPackage\nimport com.facebook.react.bridge.NativeModule\nimport com.facebook.react.bridge.ReactApplicationContext\nimport com.facebook.react.uimanager.ViewManager\n\nclass ComfortableOverlayPackage : ReactPackage {\n  override fun createNativeModules(reactContext: ReactApplicationContext): List<NativeModule> =\n    listOf(ComfortableOverlayModule(reactContext))\n\n  override fun createViewManagers(reactContext: ReactApplicationContext): List<ViewManager<*, *>> =\n    emptyList()\n}\n";
const OVERLAY_SERVICE_KT = "package com.comfortableai.torncopilot\n\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.app.Service\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.ServiceInfo\nimport android.graphics.BitmapFactory\nimport android.graphics.Color\nimport android.graphics.PixelFormat\nimport android.graphics.Typeface\nimport android.graphics.drawable.GradientDrawable\nimport android.os.Build\nimport android.os.Handler\nimport android.os.IBinder\nimport android.os.Looper\nimport android.os.SystemClock\nimport android.text.Spannable\nimport android.text.SpannableString\nimport android.text.TextPaint\nimport android.text.TextUtils\nimport android.text.style.CharacterStyle\nimport android.text.style.ForegroundColorSpan\nimport android.text.style.UpdateAppearance\nimport android.util.Base64\nimport android.view.Gravity\nimport android.view.HapticFeedbackConstants\nimport android.view.MotionEvent\nimport android.view.View\nimport android.view.WindowManager\nimport android.widget.ImageView\nimport android.widget.LinearLayout\nimport android.widget.TextView\nimport androidx.core.app.NotificationCompat\nimport androidx.core.app.ServiceCompat\nimport org.json.JSONObject\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport java.util.concurrent.Executors\nimport java.util.concurrent.ScheduledFuture\nimport java.util.concurrent.TimeUnit\nimport kotlin.math.abs\nimport kotlin.math.max\nimport kotlin.math.min\n\nclass ComfortableOverlayService : Service() {\n  private class GlowSpan(private val radius: Float, private val glowColor: Int) : CharacterStyle(), UpdateAppearance {\n    override fun updateDrawState(tp: TextPaint) {\n      tp.setShadowLayer(radius, 0f, 0f, glowColor)\n    }\n  }\n\n  private fun decodeInlineLogo(base64: String): android.graphics.Bitmap? = try {\n    val bytes = Base64.decode(base64, Base64.DEFAULT)\n    BitmapFactory.decodeByteArray(bytes, 0, bytes.size)\n  } catch (_: Exception) {\n    null\n  }\n\n  private val HUD_WORDMARK_BASE64 = \"\"\n  private val HUD_TP_BASE64 = \"\"\n\n  companion object {\n    const val ACTION_START = \"com.comfortableai.torncopilot.START_HUD\"\n    const val ACTION_STOP = \"com.comfortableai.torncopilot.STOP_HUD\"\n    const val ACTION_HOST_VISIBILITY = \"com.comfortableai.torncopilot.HOST_VISIBILITY\"\n    const val EXTRA_HOST_VISIBLE = \"comfortable_host_visible\"\n    const val ACTION_UPDATE_PREFS = \"com.comfortableai.torncopilot.UPDATE_HUD_PREFS\"\n    const val ACTION_RESET_POSITION = \"com.comfortableai.torncopilot.RESET_HUD_POSITION\"\n    const val EXTRA_API_KEY = \"comfortable_api_key\"\n    private const val CHANNEL_ID = \"comfortable-hud\"\n    private const val ATTACK_CHANNEL_ID = \"tornpulse-attack-alerts\"\n    private const val NOTIFICATION_ID = 606\n    private const val ATTACK_NOTIFICATION_BASE = 9000\n    @Volatile var isRunning: Boolean = false\n  }\n\n  private data class BarState(\n    val current: Int,\n    val maximum: Int,\n    val increment: Int,\n    val interval: Int,\n    val tickTime: Int,\n    val fullTime: Int,\n  )\n\n  private data class AttackState(\n    val id: Long,\n    val result: String,\n    val attackerName: String?,\n    val isStealthed: Boolean,\n    val ended: Long,\n  )\n\n  private data class Snapshot(\n    val life: BarState,\n    val happy: BarState,\n    val energy: BarState,\n    val nerve: BarState,\n    val drug: Int,\n    val booster: Int,\n    val medical: Int,\n    val statusState: String,\n    val statusDescription: String,\n    val statusUntil: Long,\n    val attackAccess: Boolean,\n    val latestAttack: AttackState?,\n    val receivedElapsed: Long,\n  )\n\n  private val handler = Handler(Looper.getMainLooper())\n  private val executor = Executors.newSingleThreadScheduledExecutor()\n  private var pollFuture: ScheduledFuture<*>? = null\n  private var apiKey: String? = null\n  @Volatile private var snapshot: Snapshot? = null\n  @Volatile private var lastError: String? = null\n  private var attackBaselineReady = false\n  private var lastSeenAttackId = 0L\n  private var statusBaselineReady = false\n  private var lastStatusState = \"\"\n  private var eventTickerMessage: String? = null\n  private var eventTickerColor: Int = Color.rgb(227, 83, 96)\n  private var eventTickerUntilElapsed = 0L\n\n  private lateinit var windowManager: WindowManager\n  private var overlayView: LinearLayout? = null\n  private var headerRowView: LinearLayout? = null\n  private var accentRailView: View? = null\n  private var logoViewRef: ImageView? = null\n  private var statusText: TextView? = null\n  private var collapseText: TextView? = null\n  private var statsRow: LinearLayout? = null\n  private var lifeValueText: TextView? = null\n  private var happinessValueText: TextView? = null\n  private var energyValueText: TextView? = null\n  private var nerveValueText: TextView? = null\n  private var lifeCooldownText: TextView? = null\n  private var happinessCooldownText: TextView? = null\n  private var energyCooldownText: TextView? = null\n  private var nerveCooldownText: TextView? = null\n  private var cooldownRowView: LinearLayout? = null\n  private var drugCooldownText: TextView? = null\n  private var boosterCooldownText: TextView? = null\n  private var medicalCooldownText: TextView? = null\n  private var tornClockRowView: LinearLayout? = null\n  private var tornClockTimeText: TextView? = null\n  private var tornHourCountdownText: TextView? = null\n  private var hudFooterView: TextView? = null\n  @Volatile private var tornServerEpochSeconds = 0L\n  @Volatile private var tornServerSyncElapsed = 0L\n  private var cooldownText: TextView? = null\n  private var eventTickerText: TextView? = null\n  private var detailText: TextView? = null\n  private var params: WindowManager.LayoutParams? = null\n  private var expanded = false\n  private var positionLocked = false\n  private var hudCollapsed = true\n  private var compactHud = false\n  private var currentMinWidthDp = 224\n  private var currentCollapsedWidthDp = 60\n  private var currentExpandedLogoSizeDp = 11\n  private var currentCollapsedLogoSizeDp = 32\n  private var currentExpandedLogoWidthDp = 138\n  private var currentExpandedLogoHeightDp = 26\n  private var currentCollapsedLogoWidthDp = 40\n  private var currentCollapsedLogoHeightDp = 32\n\n  private val ticker = object : Runnable {\n    override fun run() {\n      render()\n      handler.postDelayed(this, 1000)\n    }\n  }\n\n  override fun onCreate() {\n    super.onCreate()\n    windowManager = getSystemService(Context.WINDOW_SERVICE) as WindowManager\n    handler.post(ticker)\n  }\n\n  override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {\n    if (intent?.action == ACTION_STOP) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n    if (intent?.action == ACTION_UPDATE_PREFS) {\n      if (isRunning) handler.post { rebuildOverlay(true) }\n      return START_NOT_STICKY\n    }\n    if (intent?.action == ACTION_RESET_POSITION) {\n      if (isRunning) handler.post { rebuildOverlay(false) }\n      return START_NOT_STICKY\n    }\n\n    if (intent?.action == ACTION_HOST_VISIBILITY) {\n      val hostVisible = intent.getBooleanExtra(EXTRA_HOST_VISIBLE, false)\n      handler.post { overlayView?.visibility = if (hostVisible) View.GONE else View.VISIBLE }\n      return START_NOT_STICKY\n    }\n\n    startAsForeground()\n    val incomingKey = intent?.getStringExtra(EXTRA_API_KEY)\n    if (!incomingKey.isNullOrBlank()) apiKey = incomingKey\n\n    if (apiKey.isNullOrBlank()) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    try {\n      ensureOverlay()\n    } catch (_: Exception) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    isRunning = true\n    startPolling()\n    return START_NOT_STICKY\n  }\n\n  override fun onBind(intent: Intent?): IBinder? = null\n\n  override fun onDestroy() {\n    isRunning = false\n    apiKey = null\n    handler.removeCallbacks(ticker)\n    pollFuture?.cancel(true)\n    executor.shutdownNow()\n    overlayView?.let {\n      try { windowManager.removeView(it) } catch (_: Exception) {}\n    }\n    overlayView = null\n    stopForeground(STOP_FOREGROUND_REMOVE)\n    super.onDestroy()\n  }\n\n  private fun startAsForeground() {\n    val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n      manager.createNotificationChannel(\n        NotificationChannel(CHANNEL_ID, \"TornPulse HUD\", NotificationManager.IMPORTANCE_LOW).apply {\n          description = \"Keeps the TornPulse floating Torn HUD running\"\n          setShowBadge(false)\n        }\n      )\n      manager.createNotificationChannel(\n        NotificationChannel(ATTACK_CHANNEL_ID, \"TornPulse Attack Alerts\", NotificationManager.IMPORTANCE_HIGH).apply {\n          description = \"Alerts when the live TornPulse HUD detects a new incoming attack\"\n          enableVibration(true)\n          vibrationPattern = longArrayOf(0, 250, 120, 250)\n        }\n      )\n    }\n\n    val launchIntent = packageManager.getLaunchIntentForPackage(packageName)\n    val launchPending = launchIntent?.let {\n      PendingIntent.getActivity(this, 0, it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n    val stopIntent = Intent(this, ComfortableOverlayService::class.java).apply { action = ACTION_STOP }\n    val stopPending = PendingIntent.getService(this, 1, stopIntent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n\n    val notification = NotificationCompat.Builder(this, CHANNEL_ID)\n      .setSmallIcon(applicationInfo.icon)\n      .setContentTitle(\"TornPulse HUD is running\")\n      .setContentText(\"Health, Energy, Nerve and Torn status are staying visible.\")\n      .setOngoing(true)\n      .setOnlyAlertOnce(true)\n      .setCategory(NotificationCompat.CATEGORY_SERVICE)\n      .setPriority(NotificationCompat.PRIORITY_LOW)\n      .setContentIntent(launchPending)\n      .addAction(android.R.drawable.ic_menu_close_clear_cancel, \"Stop HUD\", stopPending)\n      .build()\n\n    if (Build.VERSION.SDK_INT >= 34) {\n      ServiceCompat.startForeground(this, NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE)\n    } else {\n      startForeground(NOTIFICATION_ID, notification)\n    }\n  }\n\n  private fun ensureOverlay() {\n    if (overlayView != null) return\n\n    val prefs = getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n    val preset = prefs.getString(\"hud_preset\", \"standard\") ?: \"standard\"\n    val compact = preset == \"compact\"\n    val large = preset == \"large\"\n    val minWidthDp = when {\n      compact -> 306\n      large -> 378\n      else -> 354\n    }\n    val collapsedWidthDp = when {\n      compact -> 100\n      large -> 126\n      else -> 114\n    }\n    hudCollapsed = prefs.getBoolean(\"hud_collapsed\", false)\n    compactHud = compact\n    currentMinWidthDp = minWidthDp\n    currentCollapsedWidthDp = collapsedWidthDp\n    val horizontalPadding = when {\n      compact -> 6\n      large -> 10\n      else -> 8\n    }\n    val verticalPadding = when {\n      compact -> 1\n      large -> 2\n      else -> 1\n    }\n    val headerSize = when {\n      compact -> 5.5f\n      large -> 6.5f\n      else -> 6f\n    }\n    val logoSize = when {\n      compact -> 10\n      large -> 12\n      else -> 11\n    }\n    currentExpandedLogoSizeDp = logoSize\n    currentCollapsedLogoSizeDp = when {\n      compact -> 30\n      large -> 36\n      else -> 32\n    }\n    currentExpandedLogoWidthDp = when {\n      compact -> 150\n      large -> 190\n      else -> 170\n    }\n    currentExpandedLogoHeightDp = when {\n      compact -> 92\n      large -> 117\n      else -> 105\n    }\n    currentCollapsedLogoWidthDp = when {\n      compact -> 96\n      large -> 122\n      else -> 110\n    }\n    currentCollapsedLogoHeightDp = when {\n      compact -> 39\n      large -> 50\n      else -> 45\n    }\n    val statLabelSize = when {\n      compact -> 5f\n      large -> 5.8f\n      else -> 5.3f\n    }\n    val barsSize = when {\n      compact -> 8.5f\n      large -> 10.5f\n      else -> 9.3f\n    }\n    val cooldownSize = when {\n      compact -> 5f\n      large -> 5.8f\n      else -> 5.3f\n    }\n    val tickerSize = when {\n      compact -> 5f\n      large -> 5.8f\n      else -> 5.3f\n    }\n    val detailSize = when {\n      compact -> 5f\n      large -> 5.8f\n      else -> 5.3f\n    }\n\n    val root = LinearLayout(this).apply {\n      // TORNPULSE_HUD_CONCEPT_REBUILD\n      orientation = LinearLayout.VERTICAL\n      setPadding(\n        if (hudCollapsed) 0 else dp(8),\n        if (hudCollapsed) 0 else dp(7),\n        if (hudCollapsed) 0 else dp(8),\n        if (hudCollapsed) 0 else dp(7)\n      )\n      minimumWidth = dp(if (hudCollapsed) collapsedWidthDp else minWidthDp)\n      elevation = 0f\n      background = null\n    }\n\n    val accentRail = View(this).apply {\n      setBackgroundColor(Color.TRANSPARENT)\n      visibility = View.GONE\n    }\n    accentRailView = accentRail\n    root.addView(accentRail, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(1)).apply { bottomMargin = dp(3) })\n\n    val headerRow = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = if (hudCollapsed) Gravity.CENTER else Gravity.CENTER_VERTICAL\n    }\n    headerRowView = headerRow\n    val logoView = ImageView(this).apply {\n      setImageBitmap(if (hudCollapsed) decodeInlineLogo(HUD_TP_BASE64) else decodeInlineLogo(HUD_WORDMARK_BASE64))\n      scaleType = ImageView.ScaleType.FIT_CENTER\n      adjustViewBounds = true\n      contentDescription = if (hudCollapsed) \"Expand TornPulse HUD\" else \"Collapse TornPulse HUD\"\n    }\n    logoViewRef = logoView\n    val initialLogoWidthDp = if (hudCollapsed) currentCollapsedLogoWidthDp else currentExpandedLogoWidthDp\n    val initialLogoHeightDp = if (hudCollapsed) currentCollapsedLogoHeightDp else currentExpandedLogoHeightDp\n    headerRow.addView(logoView, LinearLayout.LayoutParams(dp(initialLogoWidthDp), dp(initialLogoHeightDp)))\n    statusText = makeText(\"CONNECTING\", headerSize + 1f, Color.rgb(176, 183, 193), true).also {\n      it.letterSpacing = 0.14f\n      it.typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD_ITALIC)\n      it.setPadding(dp(10), 0, 0, 0)\n      it.textAlignment = View.TEXT_ALIGNMENT_VIEW_END\n      it.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n      headerRow.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    root.addView(headerRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n\n    // TORNPULSE_DIGITAL_TORN_CLOCK — a server-synchronized UTC/TCT display.\n    val tornClockRow = LinearLayout(this).apply {\n      orientation = LinearLayout.VERTICAL\n      gravity = Gravity.CENTER\n      setPadding(dp(8), dp(7), dp(8), dp(7))\n      minimumHeight = dp(78)\n      visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n      background = GradientDrawable(\n        GradientDrawable.Orientation.TOP_BOTTOM,\n        intArrayOf(Color.rgb(8, 10, 12), Color.rgb(2, 3, 5))\n      ).apply {\n        shape = GradientDrawable.RECTANGLE\n        cornerRadius = dp(6).toFloat()\n        setStroke(dp(1), Color.argb(205, 198, 45, 53))\n      }\n    }\n    makeText(\"TORN CITY  •  SERVER TIME\", maxOf(6.8f, cooldownSize - 1.2f), Color.rgb(200, 69, 75), true).also {\n      it.typeface = Typeface.create(Typeface.MONOSPACE, Typeface.BOLD)\n      it.letterSpacing = 0.12f\n      it.includeFontPadding = false\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      tornClockRow.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    tornClockTimeText = makeText(\"--:--:--\", maxOf(17f, barsSize + 3.5f), Color.rgb(248, 249, 250), true).also {\n      it.typeface = Typeface.create(Typeface.MONOSPACE, Typeface.BOLD)\n      it.letterSpacing = 0.08f\n      it.setPadding(0, dp(3), 0, 0)\n      it.includeFontPadding = false\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      tornClockRow.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    tornHourCountdownText = makeText(\"NEXT HOUR  --:--:--\", maxOf(7.2f, cooldownSize - .4f), Color.rgb(205, 209, 215), true).also {\n      it.typeface = Typeface.create(Typeface.MONOSPACE, Typeface.BOLD)\n      it.letterSpacing = 0.055f\n      it.setPadding(0, dp(3), 0, 0)\n      it.includeFontPadding = false\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      tornClockRow.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    val timeAccent = View(this).apply { background = GradientDrawable().apply { shape = GradientDrawable.RECTANGLE; cornerRadius = dp(2).toFloat(); setColor(Color.rgb(227,52,60)) } }\n    tornClockRow.addView(timeAccent, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(2)).apply { topMargin = dp(5) })\n    tornClockRowView = tornClockRow\n    root.addView(tornClockRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(3) })\n\n    val statContainer = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = Gravity.CENTER\n      setPadding(0, dp(1), 0, 0)\n      visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    }\n    fun makeStatColumn(label: String, color: Int): Triple<LinearLayout, TextView, TextView> {\n      val column = LinearLayout(this).apply {\n        orientation = LinearLayout.VERTICAL\n        gravity = Gravity.CENTER\n        setPadding(dp(6), dp(4), dp(6), dp(4))\n        minimumHeight = dp(98)\n        background = GradientDrawable().apply {\n          shape = GradientDrawable.RECTANGLE\n          cornerRadius = dp(6).toFloat()\n          setColor(Color.argb(242, 2, 3, 5))\n          setStroke(dp(1), Color.argb(190, Color.red(color), Color.green(color), Color.blue(color)))\n        }\n      }\n      val head = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }\n      val iconShell = LinearLayout(this).apply {\n        gravity = Gravity.CENTER\n        background = GradientDrawable().apply {\n          shape = GradientDrawable.RECTANGLE\n          cornerRadius = dp(6).toFloat()\n          setColor(Color.argb(34, Color.red(color), Color.green(color), Color.blue(color)))\n          setStroke(dp(1), Color.argb(205, Color.red(color), Color.green(color), Color.blue(color)))\n        }\n      }\n      iconShell.addView(makeHudGlyph(label, color, 18), LinearLayout.LayoutParams(dp(18), dp(18)))\n      val labelView = makeText(label, maxOf(7.5f, statLabelSize + 0.8f), color, true).apply {\n        letterSpacing = 0.055f; typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD); includeFontPadding = false; maxLines = 1\n      }\n      head.addView(iconShell, LinearLayout.LayoutParams(dp(34), dp(34)).apply { rightMargin = dp(4) })\n      head.addView(labelView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      val valueView = makeText(\"-- / --\", maxOf(13.5f, barsSize + 0.5f), Color.rgb(247, 248, 250), true).apply {\n        typeface = Typeface.create(\"sans-serif-medium\", Typeface.BOLD); setPadding(0, dp(6), 0, 0); includeFontPadding = false; maxLines = 1; textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      val timerView = makeText(\"--\", maxOf(7.3f, statLabelSize + 0.1f), Color.rgb(190, 196, 204), true).apply {\n        typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD); setPadding(0, dp(4), 0, 0); includeFontPadding = false; maxLines = 1; textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      val accent = View(this).apply { background = GradientDrawable().apply { shape = GradientDrawable.RECTANGLE; cornerRadius = dp(3).toFloat(); setColor(color) } }\n      column.addView(head, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      column.addView(valueView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      column.addView(timerView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      column.addView(accent, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(3)).apply { topMargin = dp(4); leftMargin = dp(2); rightMargin = dp(2) })\n      return Triple(column, valueView, timerView)\n    }\n    val lifeStat = makeStatColumn(\"HEALTH\", Color.rgb(74, 144, 226))\n    val energyStat = makeStatColumn(\"ENERGY\", Color.rgb(139, 195, 74))\n    val nerveStat = makeStatColumn(\"NERVE\", Color.rgb(231, 76, 60))\n    val happinessStat = makeStatColumn(\"HAPPINESS\", Color.rgb(216, 200, 91))\n    statContainer.addView(lifeStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(2) })\n    statContainer.addView(energyStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(1); rightMargin = dp(1) })\n    statContainer.addView(nerveStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(1); rightMargin = dp(1) })\n    statContainer.addView(happinessStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(2) })\n    lifeValueText = lifeStat.second\n    energyValueText = energyStat.second\n    nerveValueText = nerveStat.second\n    happinessValueText = happinessStat.second\n    lifeCooldownText = lifeStat.third\n    energyCooldownText = energyStat.third\n    nerveCooldownText = nerveStat.third\n    happinessCooldownText = happinessStat.third\n    statsRow = statContainer\n    root.addView(statContainer, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply {\n      topMargin = dp(3)\n    })\n\n    val cooldownRow = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = Gravity.CENTER\n      visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    }\n    fun makeCooldownChip(label: String, labelColor: Int): Pair<LinearLayout, TextView> {\n      val chip = LinearLayout(this).apply {\n        orientation = LinearLayout.VERTICAL\n        gravity = Gravity.CENTER\n        setPadding(dp(4), dp(4), dp(4), dp(4))\n        minimumHeight = dp(62)\n        background = GradientDrawable().apply {\n          shape = GradientDrawable.RECTANGLE\n          cornerRadius = dp(6).toFloat()\n          setColor(Color.argb(242, 2, 3, 5))\n          setStroke(dp(1), Color.argb(175, Color.red(labelColor), Color.green(labelColor), Color.blue(labelColor)))\n        }\n      }\n      val head = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }\n      val iconShell = LinearLayout(this).apply {\n        gravity = Gravity.CENTER\n        background = GradientDrawable().apply {\n          shape = GradientDrawable.RECTANGLE\n          cornerRadius = dp(6).toFloat()\n          setColor(Color.argb(32, Color.red(labelColor), Color.green(labelColor), Color.blue(labelColor)))\n          setStroke(dp(1), Color.argb(190, Color.red(labelColor), Color.green(labelColor), Color.blue(labelColor)))\n        }\n      }\n      iconShell.addView(makeHudGlyph(label, labelColor, 16), LinearLayout.LayoutParams(dp(16), dp(16)))\n      head.addView(iconShell, LinearLayout.LayoutParams(dp(30), dp(30)).apply { rightMargin = dp(3) })\n      val labelView = makeText(label, maxOf(7f, cooldownSize - .1f), labelColor, true).apply {\n        letterSpacing = .055f; typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD); includeFontPadding = false; maxLines = 1\n      }\n      head.addView(labelView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      val valueView = makeText(\"--\", maxOf(9.5f, cooldownSize + 1.2f), Color.rgb(95,214,132), true).apply {\n        typeface = Typeface.create(\"sans-serif-medium\", Typeface.BOLD); setPadding(0, dp(5), 0, 0); includeFontPadding = false; maxLines = 1; textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      chip.addView(head, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      chip.addView(valueView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      return Pair(chip, valueView)\n    }\n    val drugChip = makeCooldownChip(\"DRUG\", Color.rgb(173, 123, 255))\n    val boosterChip = makeCooldownChip(\"BOOSTER\", Color.rgb(226, 169, 72))\n    val medicalChip = makeCooldownChip(\"MEDICAL\", Color.rgb(111, 208, 141))\n    val scannerChip = makeCooldownChip(\"📋  BALDR LIST\", Color.rgb(111, 208, 141))\n    scannerChip.second.text = \"OPEN\"\n    scannerChip.second.setTextColor(Color.rgb(111, 208, 141))\n\n    cooldownRow.addView(drugChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(2) })\n    cooldownRow.addView(boosterChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(1); rightMargin = dp(1) })\n    cooldownRow.addView(medicalChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(1); rightMargin = dp(1) })\n    cooldownRow.addView(scannerChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(2) })\n\n    drugCooldownText = drugChip.second\n    boosterCooldownText = boosterChip.second\n    medicalCooldownText = medicalChip.second\n    cooldownRowView = cooldownRow\n    root.addView(cooldownRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply {\n      topMargin = dp(3)\n    })\n\n    hudFooterView = makeText(\"●  FLOATING HUD  •  ON SCREEN\", maxOf(6.5f, cooldownSize - 0.6f), Color.rgb(95, 214, 132), true).also {\n      it.letterSpacing = 0.08f\n      it.typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD)\n      it.setPadding(dp(3), dp(6), dp(3), 0)\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      it.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n      root.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n\n    eventTickerText = makeText(\"LIVE ACTIVITY\", maxOf(6.0f, tickerSize - 0.35f), Color.rgb(220, 224, 229), true).also {\n      it.setPadding(dp(4), dp(2), dp(4), dp(2))\n      it.setSingleLine(true)\n      it.ellipsize = TextUtils.TruncateAt.END\n      it.setHorizontallyScrolling(false)\n      it.isSelected = false\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      it.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n      it.background = GradientDrawable().apply {\n        shape = GradientDrawable.RECTANGLE\n        cornerRadius = dp(6).toFloat()\n        setColor(Color.argb(242, 3, 4, 7))\n        setStroke(dp(1), Color.argb(72, 227, 52, 60))\n      }\n      headerRow.addView(it, 1, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply {\n        leftMargin = dp(4)\n        rightMargin = dp(4)\n      })\n    }\n\n    positionLocked = prefs.getBoolean(\"locked\", false)\n    val display = resources.displayMetrics\n    val rightRailMigrated = prefs.getBoolean(\"right_rail_v1\", false)\n    if (!rightRailMigrated) {\n      hudCollapsed = true\n      prefs.edit().putBoolean(\"right_rail_v1\", true).putBoolean(\"collapsed\", true).apply()\n    }\n    val initialDockWidthDp = if (hudCollapsed) currentCollapsedWidthDp else currentMinWidthDp\n    val defaultRightX = max(0, display.widthPixels - dp(initialDockWidthDp) - dp(8))\n    val rightDockMigrated = prefs.getBoolean(\"right_dock_v1\", false)\n    val savedX = if (rightDockMigrated) prefs.getInt(\"x\", defaultRightX) else defaultRightX\n    if (!rightDockMigrated) {\n      prefs.edit().putBoolean(\"right_dock_v1\", true).putInt(\"x\", defaultRightX).apply()\n    }\n    val savedY = prefs.getInt(\"y\", dp(120))\n    val type = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY else WindowManager.LayoutParams.TYPE_PHONE\n\n    val lp = WindowManager.LayoutParams(\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      type,\n      WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,\n      PixelFormat.TRANSLUCENT\n    ).apply {\n      gravity = Gravity.TOP or Gravity.START\n      x = min(max(0, savedX), max(0, display.widthPixels - dp(if (hudCollapsed) collapsedWidthDp else minWidthDp)))\n      y = max(dp(36), savedY)\n    }\n\n    var initialX = 0\n    var initialY = 0\n    var initialTouchX = 0f\n    var initialTouchY = 0f\n    var touchDownElapsed = 0L\n    var moved = false\n\n    root.setOnTouchListener { _, event ->\n      when (event.actionMasked) {\n        MotionEvent.ACTION_DOWN -> {\n          initialX = lp.x\n          initialY = lp.y\n          initialTouchX = event.rawX\n          initialTouchY = event.rawY\n          touchDownElapsed = SystemClock.elapsedRealtime()\n          moved = false\n          true\n        }\n        MotionEvent.ACTION_MOVE -> {\n          val dx = event.rawX - initialTouchX\n          val dy = event.rawY - initialTouchY\n          if (!positionLocked && (abs(dx) > dp(4) || abs(dy) > dp(4))) moved = true\n          if (moved && !positionLocked) {\n            val width = max(root.width, dp(if (hudCollapsed) collapsedWidthDp else minWidthDp))\n            val height = max(root.height, dp(60))\n            lp.x = min(max(0, initialX + dx.toInt()), max(0, display.widthPixels - width))\n            lp.y = min(max(dp(30), initialY + dy.toInt()), max(dp(30), display.heightPixels - height - dp(30)))\n            try { windowManager.updateViewLayout(root, lp) } catch (_: Exception) {}\n          }\n          true\n        }\n        MotionEvent.ACTION_UP -> {\n          val heldMs = SystemClock.elapsedRealtime() - touchDownElapsed\n          if (!moved && heldMs >= 650L) {\n            positionLocked = !positionLocked\n            prefs.edit().putBoolean(\"locked\", positionLocked).apply()\n            root.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)\n            render()\n          } else if (!moved) {\n            val logoHit = if (hudCollapsed) {\n              event.x >= dp(6) && event.x <= (root.width - dp(6)) && event.y >= dp(4) && event.y <= (root.height - dp(4))\n            } else {\n              event.x >= 0 && event.x <= (root.width * 0.48f) && event.y >= 0 && event.y <= dp(currentExpandedLogoHeightDp + 22)\n            }\n            if (logoHit) {\n              hudCollapsed = !hudCollapsed\n              expanded = false\n              prefs.edit().putBoolean(\"hud_collapsed\", hudCollapsed).apply()\n              applyCollapsedState()\n              render()\n            }\n          }\n          prefs.edit().putInt(\"x\", lp.x).putInt(\"y\", lp.y).apply()\n          true\n        }\n        else -> false\n      }\n    }\n\n    windowManager.addView(root, lp)\n    overlayView = root\n    params = lp\n    render()\n  }\n\n  private fun rebuildOverlay(savePosition: Boolean) {\n    val currentParams = params\n    if (savePosition && currentParams != null) {\n      getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .putInt(\"x\", currentParams.x)\n        .putInt(\"y\", currentParams.y)\n        .apply()\n    }\n    overlayView?.let {\n      try { windowManager.removeView(it) } catch (_: Exception) {}\n    }\n    overlayView = null\n    headerRowView = null\n    accentRailView = null\n    logoViewRef = null\n    statusText = null\n    collapseText = null\n    statsRow = null\n    lifeValueText = null\n    happinessValueText = null\n    energyValueText = null\n    nerveValueText = null\n    lifeCooldownText = null\n    happinessCooldownText = null\n    energyCooldownText = null\n    nerveCooldownText = null\n    cooldownRowView = null\n    drugCooldownText = null\n    boosterCooldownText = null\n    medicalCooldownText = null\n    tornClockRowView = null\n    tornClockTimeText = null\n    tornHourCountdownText = null\n    hudFooterView = null\n    cooldownText = null\n    eventTickerText = null\n    detailText = null\n    params = null\n    expanded = false\n    ensureOverlay()\n  }\n\n  private fun makeText(value: String, size: Float, color: Int, bold: Boolean): TextView =\n    TextView(this).apply {\n      text = value\n      textSize = size\n      setTextColor(color)\n      typeface = if (bold) Typeface.DEFAULT_BOLD else Typeface.DEFAULT\n      includeFontPadding = false\n    }\n\n  private fun renderBarValue(view: TextView?, current: Int, maximum: Int, color: Int) {\n    val target = view ?: return\n    if (maximum <= 0) {\n      target.text = \"-- / --\"\n      target.setTextColor(Color.rgb(137, 145, 156))\n      return\n    }\n    val white = Color.rgb(244, 245, 246)\n    val muted = Color.rgb(137, 145, 156)\n    val currentText = current.toString()\n    val maxText = maximum.toString()\n    val text = \"$currentText / $maxText\"\n    val styled = SpannableString(text)\n    val currentStart = 0\n    val currentEnd = currentText.length\n    val slashStart = currentEnd + 1\n    val slashEnd = slashStart + 1\n    val maxStart = slashEnd + 1\n    val maxEnd = maxStart + maxText.length\n    val capped = current >= maximum\n\n    styled.setSpan(ForegroundColorSpan(if (capped) color else white), currentStart, currentEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(GlowSpan(if (capped) dp(3).toFloat() else dp(2).toFloat(), color), currentStart, currentEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(ForegroundColorSpan(if (capped) color else muted), slashStart, slashEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(ForegroundColorSpan(color), maxStart, maxEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    target.text = styled\n  }\n\n  private fun renderBars(lifeCurrent: Int, lifeMax: Int, energyCurrent: Int, energyMax: Int, nerveCurrent: Int, nerveMax: Int, happinessCurrent: Int, happinessMax: Int) {\n    renderBarValue(lifeValueText, lifeCurrent, lifeMax, Color.rgb(74, 144, 226))\n    renderBarValue(energyValueText, energyCurrent, energyMax, Color.rgb(139, 195, 74))\n    renderBarValue(nerveValueText, nerveCurrent, nerveMax, Color.rgb(231, 76, 60))\n    renderBarValue(happinessValueText, happinessCurrent, happinessMax, Color.rgb(216, 200, 91))\n  }\n\n  private fun renderEmptyBars() {\n    lifeValueText?.text = \"-- / --\"\n    energyValueText?.text = \"-- / --\"\n    nerveValueText?.text = \"-- / --\"\n    happinessValueText?.text = \"-- / --\"\n    lifeValueText?.setTextColor(Color.rgb(137, 145, 156))\n    energyValueText?.setTextColor(Color.rgb(137, 145, 156))\n    nerveValueText?.setTextColor(Color.rgb(137, 145, 156))\n    happinessValueText?.setTextColor(Color.rgb(137, 145, 156))\n  }\n\n  // TORNPULSE_CATEGORY_IMAGE_ENGINE\n  private val TP_HEALTH_ICON = \"\"\n  private val TP_ENERGY_ICON = \"\"\n  private val TP_NERVE_ICON = \"\"\n  private val TP_HAPPINESS_ICON = \"\"\n  private val TP_DRUG_ICON = \"\"\n  private val TP_BOOSTER_ICON = \"\"\n  private val TP_MEDICAL_ICON = \"\"\n  private val TP_BALDR_ICON = \"\"\n\n  private fun openBaldrList() {\n    try {\n      val intent = Intent(\n        Intent.ACTION_VIEW,\n        android.net.Uri.parse(\"https://oran.pw/baldrstargets/\")\n      ).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n      startActivity(intent)\n    } catch (_: Exception) {\n      // Keep the floating HUD stable if no browser is currently available.\n    }\n  }\n\n  private fun makeHudGlyph(kind: String, color: Int, sizeDp: Int = 18): View {\n    val normalized = kind.replace(\"📋\", \"\").trim()\n    val encoded = when (normalized) {\n      \"HEALTH\" -> TP_HEALTH_ICON\n      \"ENERGY\" -> TP_ENERGY_ICON\n      \"NERVE\" -> TP_NERVE_ICON\n      \"HAPPINESS\" -> TP_HAPPINESS_ICON\n      \"DRUG\" -> TP_DRUG_ICON\n      \"BOOSTER\" -> TP_BOOSTER_ICON\n      \"MEDICAL\" -> TP_MEDICAL_ICON\n      \"BALDR LIST\" -> TP_BALDR_ICON\n      else -> TP_BALDR_ICON\n    }\n    val bytes = Base64.decode(encoded, Base64.DEFAULT)\n    return ImageView(this).apply {\n      setImageBitmap(BitmapFactory.decodeByteArray(bytes, 0, bytes.size))\n      scaleType = ImageView.ScaleType.FIT_CENTER\n      adjustViewBounds = true\n      contentDescription = normalized\n      minimumWidth = dp(sizeDp)\n      minimumHeight = dp(sizeDp)\n      if (normalized == \"BALDR LIST\") {\n        isClickable = true\n        isFocusable = true\n        contentDescription = \"Open Baldr's List\"\n        setOnClickListener {\n          performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY)\n          openBaldrList()\n        }\n        // The glyph is placed inside the Baldr tile's visual shell. Make that\n        // shell clickable too, giving the user a practical finger-sized target.\n        post {\n          (parent as? View)?.apply {\n            isClickable = true\n            isFocusable = true\n            contentDescription = \"Open Baldr's List\"\n            setOnClickListener {\n              performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY)\n              openBaldrList()\n            }\n          }\n        }\n      }\n    }\n  }\n\n  private fun applyCollapsedState() {\n    overlayView?.post {\n      val railView = overlayView ?: return@post\n      val railParams = params ?: return@post\n      val screen = resources.displayMetrics\n      val expectedWidthDp = if (hudCollapsed) currentCollapsedWidthDp else currentMinWidthDp\n      val renderedWidth = max(railView.width, dp(expectedWidthDp))\n      railParams.x = max(0, screen.widthPixels - renderedWidth - dp(8))\n      try { windowManager.updateViewLayout(railView, railParams) } catch (_: Exception) {}\n      getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit().putInt(\"x\", railParams.x).apply()\n    }\n    val root = overlayView ?: return\n    val visible = if (hudCollapsed) View.GONE else View.VISIBLE\n\n    statsRow?.visibility = visible\n    cooldownRowView?.visibility = visible\n    tornClockRowView?.visibility = visible\n    statusText?.visibility = visible\n    accentRailView?.visibility = View.GONE\n    hudFooterView?.visibility = visible\n    detailText?.visibility = View.GONE\n\n    headerRowView?.gravity = if (hudCollapsed) Gravity.CENTER else Gravity.CENTER_VERTICAL\n    logoViewRef?.contentDescription = if (hudCollapsed) \"Expand TornPulse HUD\" else \"Collapse TornPulse HUD\"\n\n    logoViewRef?.let { logo ->\n      logo.setImageBitmap(if (hudCollapsed) decodeInlineLogo(HUD_TP_BASE64) else decodeInlineLogo(HUD_WORDMARK_BASE64))\n      val targetWidth = dp(if (hudCollapsed) currentCollapsedLogoWidthDp else currentExpandedLogoWidthDp)\n      val targetHeight = dp(if (hudCollapsed) currentCollapsedLogoHeightDp else currentExpandedLogoHeightDp)\n      val logoParams = logo.layoutParams\n      logoParams.width = targetWidth\n      logoParams.height = targetHeight\n      logo.layoutParams = logoParams\n    }\n\n    root.setPadding(\n      if (hudCollapsed) 0 else dp(8),\n      if (hudCollapsed) 0 else dp(7),\n      if (hudCollapsed) 0 else dp(8),\n      if (hudCollapsed) 0 else dp(7)\n    )\n    root.minimumWidth = dp(if (hudCollapsed) currentCollapsedLogoWidthDp else currentMinWidthDp)\n    root.elevation = 0f\n\n    root.background = null\n\n    if (hudCollapsed) eventTickerText?.visibility = View.GONE else renderEventTicker()\n\n    val lp = params\n    if (lp != null) {\n      val display = resources.displayMetrics\n      val targetWidth = dp(if (hudCollapsed) currentCollapsedLogoWidthDp else currentMinWidthDp)\n      lp.x = min(max(0, lp.x), max(0, display.widthPixels - targetWidth))\n      try { windowManager.updateViewLayout(root, lp) } catch (_: Exception) {}\n    }\n    root.requestLayout()\n  }\n\n  private fun startPolling() {\n    if (pollFuture == null || pollFuture?.isCancelled == true) {\n      pollFuture = executor.scheduleWithFixedDelay({ fetchSnapshot() }, 0, 60, TimeUnit.SECONDS)\n    } else {\n      executor.execute { fetchSnapshot() }\n    }\n  }\n\n  private fun fetchSnapshot() {\n    val key = apiKey ?: return\n    try {\n      val bars = getJson(\"/user/bars\", key).getJSONObject(\"bars\")\n      val cooldowns = getJson(\"/user/cooldowns\", key).getJSONObject(\"cooldowns\")\n      val profile = getJson(\"/user/basic\", key).getJSONObject(\"profile\")\n      val status = profile.getJSONObject(\"status\")\n\n      var attackAccess = true\n      var latestAttack: AttackState? = null\n      try {\n        val attackArray = getJson(\"/user/attacks?filters=incoming&sort=DESC&limit=1\", key).optJSONArray(\"attacks\")\n        if (attackArray != null && attackArray.length() > 0) {\n          val attack = attackArray.getJSONObject(0)\n          val attacker = attack.optJSONObject(\"attacker\")\n          latestAttack = AttackState(\n            id = attack.optLong(\"id\", 0L),\n            result = attack.optString(\"result\", \"Unknown\"),\n            attackerName = attacker?.optString(\"name\")?.takeIf { it.isNotBlank() },\n            isStealthed = attack.optBoolean(\"is_stealthed\", attacker == null),\n            ended = attack.optLong(\"ended\", attack.optLong(\"started\", 0L)),\n          )\n        }\n      } catch (_: Exception) {\n        attackAccess = false\n      }\n\n      maybeNotifyAttack(latestAttack, attackAccess)\n      maybeTrackStatus(status.optString(\"state\", \"Unknown\"))\n\n      val next = Snapshot(\n        life = readBar(bars.getJSONObject(\"life\")),\n        happy = readBar(bars.getJSONObject(\"happy\")),\n        energy = readBar(bars.getJSONObject(\"energy\")),\n        nerve = readBar(bars.getJSONObject(\"nerve\")),\n        drug = cooldowns.optInt(\"drug\", 0),\n        booster = cooldowns.optInt(\"booster\", 0),\n        medical = cooldowns.optInt(\"medical\", 0),\n        statusState = status.optString(\"state\", \"Unknown\"),\n        statusDescription = status.optString(\"description\", status.optString(\"state\", \"Unknown\")),\n        statusUntil = if (status.isNull(\"until\")) 0L else status.optLong(\"until\", 0L),\n        attackAccess = attackAccess,\n        latestAttack = latestAttack,\n        receivedElapsed = SystemClock.elapsedRealtime(),\n      )\n      snapshot = next\n      lastError = null\n      handler.post { render() }\n\n      // Sync against Torn's forum/server clock after the core snapshot is already live.\n      // A failed clock sync never takes Health/Energy/Nerve/status offline.\n      try {\n        val cacheBust = System.currentTimeMillis() / 1000L\n        val serverTime = getJson(\"/forum/timestamp?timestamp=$cacheBust\", key).optLong(\"timestamp\", 0L)\n        if (serverTime > 0L) {\n          tornServerEpochSeconds = serverTime\n          tornServerSyncElapsed = SystemClock.elapsedRealtime()\n          handler.post { renderTornClock() }\n        }\n      } catch (_: Exception) {\n        // Keep the last good Torn clock anchor if the time-only request fails.\n      }\n    } catch (e: Exception) {\n      lastError = e.message ?: \"Connection issue\"\n      handler.post { render() }\n    }\n  }\n\n  private fun getJson(path: String, key: String): JSONObject {\n    val separator = if (path.contains(\"?\")) \"&\" else \"?\"\n    val connection = URL(\"https://api.torn.com/v2$path${separator}comment=TornPulse-HUD\").openConnection() as HttpURLConnection\n    connection.connectTimeout = 12000\n    connection.readTimeout = 12000\n    connection.requestMethod = \"GET\"\n    connection.setRequestProperty(\"Authorization\", \"ApiKey $key\")\n    connection.setRequestProperty(\"Accept\", \"application/json\")\n    connection.setRequestProperty(\"User-Agent\", \"TornPulse/1.0.0\")\n    return try {\n      val code = connection.responseCode\n      val stream = if (code in 200..299) connection.inputStream else connection.errorStream\n      val body = stream?.bufferedReader()?.use { it.readText() } ?: \"{}\"\n      val json = JSONObject(body)\n      if (code !in 200..299 || json.has(\"error\")) {\n        val error = json.optJSONObject(\"error\")\n        throw IllegalStateException(error?.optString(\"error\") ?: error?.optString(\"message\") ?: \"Torn API error ($code)\")\n      }\n      json\n    } finally {\n      connection.disconnect()\n    }\n  }\n\n  private fun readBar(json: JSONObject): BarState {\n    val bar = BarState(\n      current = json.optInt(\"current\", 0),\n      maximum = json.optInt(\"maximum\", 0),\n      increment = json.optInt(\"increment\", 0),\n      interval = json.optInt(\"interval\", 0),\n      tickTime = max(0, json.optInt(\"tick_time\", 0)),\n      fullTime = max(0, json.optInt(\"full_time\", 0)),\n    )\n    if (bar.maximum <= 0) throw IllegalStateException(\"Invalid Torn bar response\")\n    return bar\n  }\n\n  private fun projected(bar: BarState, elapsed: Int): Int {\n    if (bar.current >= bar.maximum) return bar.maximum\n    if (bar.interval <= 0 || bar.increment <= 0) return bar.current\n    val firstTick = if (bar.tickTime > 0) bar.tickTime else bar.interval\n    if (elapsed < firstTick) return bar.current\n    val ticks = 1 + (elapsed - firstTick) / bar.interval\n    return min(bar.maximum, bar.current + ticks * bar.increment)\n  }\n\n  private fun remaining(initial: Int, elapsed: Int): Int = max(0, initial - elapsed)\n\n  private fun render() {\n    renderTornClock()\n    val snap = snapshot\n    if (snap == null) {\n      statusText?.text = if (lastError == null) \"CONNECTING\" else \"OFFLINE\"\n      statusText?.setTextColor(if (lastError == null) Color.rgb(176, 183, 193) else Color.rgb(227, 83, 96))\n      renderEmptyBars()\n      lifeCooldownText?.text = \"--\"\n      energyCooldownText?.text = \"--\"\n      nerveCooldownText?.text = \"--\"\n      happinessCooldownText?.text = \"--\"\n      renderCooldownStrip(-1, -1, -1)\n      renderEventTicker()\n      return\n    }\n\n    val elapsed = max(0, ((SystemClock.elapsedRealtime() - snap.receivedElapsed) / 1000L).toInt())\n    val life = projected(snap.life, elapsed)\n    val energy = projected(snap.energy, elapsed)\n    val nerve = projected(snap.nerve, elapsed)\n    val happiness = projected(snap.happy, elapsed)\n    val stale = elapsed > 120 || lastError != null\n    val nowUnix = currentTornEpochSeconds() ?: (System.currentTimeMillis() / 1000L)\n    val statusRemaining = if (snap.statusUntil > nowUnix) (snap.statusUntil - nowUnix).toInt() else 0\n    val state = snap.statusState.ifBlank { \"Unknown\" }.uppercase()\n    val headerStatus = if (statusRemaining > 0) \"$state ${formatDuration(statusRemaining)}\" else state\n    val lockMark = if (positionLocked) \" • 🔒\" else \"\"\n\n    statusText?.text = if (stale) \"CHECKING$lockMark\" else \"$headerStatus$lockMark\"\n    val statusColor = when {\n      stale -> Color.rgb(225, 168, 52)\n      state.contains(\"OKAY\") -> Color.rgb(97, 215, 133)\n      state.contains(\"HOSPITAL\") -> Color.rgb(227, 83, 96)\n      state.contains(\"JAIL\") -> Color.rgb(225, 168, 52)\n      else -> Color.rgb(213, 47, 50)\n    }\n    statusText?.setTextColor(statusColor)\n    renderBars(life, snap.life.maximum, energy, snap.energy.maximum, nerve, snap.nerve.maximum, happiness, snap.happy.maximum)\n    renderEventTicker()\n\n    val lifeFull = if (life >= snap.life.maximum) \"CAPPED\" else formatDuration(remaining(snap.life.fullTime, elapsed))\n    val energyFull = if (energy >= snap.energy.maximum) \"CAPPED\" else formatDuration(remaining(snap.energy.fullTime, elapsed))\n    val nerveFull = if (nerve >= snap.nerve.maximum) \"CAPPED\" else formatDuration(remaining(snap.nerve.fullTime, elapsed))\n    val timerMuted = Color.rgb(188, 193, 200)\n    lifeCooldownText?.apply {\n      text = lifeFull\n      setTextColor(if (life >= snap.life.maximum) Color.rgb(74, 144, 226) else timerMuted)\n    }\n    energyCooldownText?.apply {\n      text = energyFull\n      setTextColor(if (energy >= snap.energy.maximum) Color.rgb(139, 195, 74) else timerMuted)\n    }\n    nerveCooldownText?.apply {\n      text = nerveFull\n      setTextColor(if (nerve >= snap.nerve.maximum) Color.rgb(231, 76, 60) else timerMuted)\n    }\n    happinessCooldownText?.apply {\n      text = \"CURRENT\"\n      setTextColor(Color.rgb(216, 200, 91))\n    }\n    val drugSeconds = remaining(snap.drug, elapsed)\n    val boosterSeconds = remaining(snap.booster, elapsed)\n    val medicalSeconds = remaining(snap.medical, elapsed)\n    renderCooldownStrip(drugSeconds, boosterSeconds, medicalSeconds)\n  }\n\n  private fun maybeNotifyAttack(attack: AttackState?, attackAccess: Boolean) {\n    if (!attackAccess) return\n    if (!attackBaselineReady) {\n      attackBaselineReady = true\n      if (attack != null && attack.id > 0L) lastSeenAttackId = attack.id\n      return\n    }\n    if (attack == null || attack.id <= 0L || attack.id == lastSeenAttackId) return\n    lastSeenAttackId = attack.id\n\n    val who = attack.attackerName ?: if (attack.isStealthed) \"UNKNOWN / STEALTH\" else \"UNKNOWN ATTACKER\"\n    val result = attack.result.ifBlank { \"ATTACKED\" }.uppercase()\n    val tickerMessage = if (result.contains(\"MUG\")) \"MUGGED BY $who\" else \"ATTACKED BY $who • $result\"\n    showHudEvent(tickerMessage, Color.rgb(227, 83, 96), 35)\n\n    val prefs = getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n    if (!prefs.getBoolean(\"attack_alerts\", true)) return\n\n    val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    val launchIntent = packageManager.getLaunchIntentForPackage(packageName)\n    val launchPending = launchIntent?.let {\n      PendingIntent.getActivity(this, 2, it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n    val notificationWho = attack.attackerName ?: if (attack.isStealthed) \"Unknown / stealth\" else \"Unknown attacker\"\n    val notification = NotificationCompat.Builder(this, ATTACK_CHANNEL_ID)\n      .setSmallIcon(applicationInfo.icon)\n      .setContentTitle(\"TornPulse • Incoming attack\")\n      .setContentText(\"$notificationWho • ${attack.result}\")\n      .setStyle(NotificationCompat.BigTextStyle().bigText(\"$notificationWho • ${attack.result}\"))\n      .setPriority(NotificationCompat.PRIORITY_HIGH)\n      .setCategory(NotificationCompat.CATEGORY_EVENT)\n      .setAutoCancel(true)\n      .setContentIntent(launchPending)\n      .build()\n    manager.notify(ATTACK_NOTIFICATION_BASE + (attack.id % 1000L).toInt(), notification)\n  }\n\n  private fun maybeTrackStatus(newState: String) {\n    val normalized = newState.trim().uppercase()\n    if (!statusBaselineReady) {\n      statusBaselineReady = true\n      lastStatusState = normalized\n      return\n    }\n    val previous = lastStatusState\n    lastStatusState = normalized\n    if (previous.contains(\"HOSPITAL\") && !normalized.contains(\"HOSPITAL\")) {\n      showHudEvent(\"RELEASED FROM HOSPITAL\", Color.rgb(97, 215, 133), 30)\n    } else if (previous.contains(\"JAIL\") && !normalized.contains(\"JAIL\")) {\n      showHudEvent(\"RELEASED FROM JAIL\", Color.rgb(97, 215, 133), 30)\n    }\n  }\n\n  private fun showHudEvent(message: String, color: Int, seconds: Int) {\n    eventTickerMessage = message\n    eventTickerColor = color\n    eventTickerUntilElapsed = SystemClock.elapsedRealtime() + seconds * 1000L\n    handler.post { renderEventTicker() }\n  }\n\n  private fun currentTornEpochSeconds(): Long? {\n    if (tornServerEpochSeconds <= 0L || tornServerSyncElapsed <= 0L) return null\n    val elapsedSeconds = ((SystemClock.elapsedRealtime() - tornServerSyncElapsed) / 1000L).coerceAtLeast(0L)\n    return tornServerEpochSeconds + elapsedSeconds\n  }\n\n  private fun clockStamp(totalSeconds: Long): String {\n    val hours = totalSeconds / 3600L\n    val minutes = (totalSeconds % 3600L) / 60L\n    val seconds = totalSeconds % 60L\n    return hours.toString().padStart(2, '0') + \":\" +\n      minutes.toString().padStart(2, '0') + \":\" +\n      seconds.toString().padStart(2, '0')\n  }\n\n  private fun renderTornClock() {\n    val row = tornClockRowView ?: return\n    if (hudCollapsed) {\n      row.visibility = View.GONE\n      return\n    }\n    row.visibility = View.VISIBLE\n    // Torn time is UTC. Prefer Torn's own timestamp anchor; use device UTC\n    // only during the few moments before the first successful server sync.\n    val now = currentTornEpochSeconds() ?: (System.currentTimeMillis() / 1000L)\n\n    val daySeconds = ((now % 86400L) + 86400L) % 86400L\n    val secondsIntoHour = daySeconds % 3600L\n    val remaining = if (secondsIntoHour == 0L) 0L else 3600L - secondsIntoHour\n    tornClockTimeText?.apply {\n      text = clockStamp(daySeconds)\n      setTextColor(Color.rgb(205, 209, 213))\n    }\n    tornHourCountdownText?.apply {\n      text = \"NEXT HOUR  ${clockStamp(remaining)}\"\n      setTextColor(when {\n        remaining in 1L..10L -> Color.rgb(227, 83, 96)\n        remaining in 11L..60L -> Color.rgb(215, 165, 68)\n        remaining == 0L -> Color.rgb(111, 208, 141)\n        else -> Color.rgb(244, 245, 246)\n      })\n    }\n  }\n\n  private fun renderCooldownStrip(drugSeconds: Int, boosterSeconds: Int, medicalSeconds: Int) {\n    fun update(view: TextView?, seconds: Int) {\n      val target = view ?: return\n      when {\n        seconds < 0 -> {\n          target.text = \"--\"\n          target.setTextColor(Color.rgb(170, 175, 181))\n        }\n        seconds == 0 -> {\n          target.text = \"READY\"\n          target.setTextColor(Color.rgb(111, 208, 141))\n        }\n        else -> {\n          target.text = formatDuration(seconds)\n          target.setTextColor(Color.rgb(236, 238, 240))\n        }\n      }\n    }\n    update(drugCooldownText, drugSeconds)\n    update(boosterCooldownText, boosterSeconds)\n    update(medicalCooldownText, medicalSeconds)\n    cooldownRowView?.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n  }\n\n  private fun renderEventTicker() {\n    val view = eventTickerText ?: return\n    if (hudCollapsed) {\n      view.visibility = View.GONE\n      return\n    }\n\n    val activeEvent = eventTickerMessage?.takeIf {\n      it.isNotBlank()\n    }\n\n    var display: String\n    var color = Color.rgb(205, 210, 217)\n\n    if (activeEvent != null) {\n      display = \"ALERT  •  $activeEvent\"\n      color = eventTickerColor\n    } else {\n      val snap = snapshot\n      if (snap == null) {\n        display = \"TORNPULSE  •  CONNECTING\"\n        color = Color.rgb(170, 177, 187)\n      } else {\n        val latest = snap.latestAttack\n        if (latest != null) {\n          val who = latest.attackerName ?: if (latest.isStealthed) \"UNKNOWN / STEALTH\" else \"UNKNOWN ATTACKER\"\n          val nowUnix = currentTornEpochSeconds() ?: (System.currentTimeMillis() / 1000L)\n          val age = if (latest.ended > 0L) \"  •  ${formatAge(max(0L, nowUnix - latest.ended).toInt())}\" else \"\"\n          display = \"LAST ATTACK  •  $who  •  ${latest.result}\"\n          color = Color.rgb(227, 83, 96)\n        } else if (!snap.attackAccess) {\n          display = \"ACTIVITY  •  LIMITED API KEY FOR INCOMING ATTACKS\"\n          color = Color.rgb(215, 165, 68)\n        } else {\n          val liveStatus = snap.statusDescription.ifBlank { \"OKAY\" }\n          display = \"LIVE  •  $liveStatus\"\n          color = Color.rgb(111, 208, 141)\n        }\n      }\n    }\n\n    if (view.text.toString() != display) {\n      view.text = display\n    }\n    view.isSelected = false\n    view.setTextColor(color)\n    view.background = GradientDrawable().apply {\n      shape = GradientDrawable.RECTANGLE\n      cornerRadius = dp(6).toFloat()\n      setColor(Color.argb(242, 3, 4, 7))\n      setStroke(dp(1), Color.argb(105, Color.red(color), Color.green(color), Color.blue(color)))\n    }\n    view.visibility = View.VISIBLE\n  }\n\n  private fun formatAge(totalSeconds: Int): String {\n    if (totalSeconds < 10) return \"JUST NOW\"\n    if (totalSeconds < 60) return \"${totalSeconds}s AGO\"\n    val minutes = totalSeconds / 60\n    if (minutes < 60) return \"${minutes}m AGO\"\n    val hours = minutes / 60\n    if (hours < 24) return \"${hours}h AGO\"\n    return \"${hours / 24}d AGO\"\n  }\n\n  private fun formatDuration(totalSeconds: Int): String {\n    if (totalSeconds <= 0) return \"READY\"\n    val hours = totalSeconds / 3600\n    val minutes = (totalSeconds % 3600) / 60\n    val seconds = totalSeconds % 60\n    return when {\n      hours > 0 -> \"${hours}h ${minutes}m\"\n      minutes > 0 -> \"${minutes}m ${seconds}s\"\n      else -> \"${seconds}s\"\n    }\n  }\n\n  private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()\n}\n";

function ensurePermission(manifest, name) {
  manifest['uses-permission'] = manifest['uses-permission'] || [];
  const exists = manifest['uses-permission'].some(item => item?.$?.['android:name'] === name);
  if (!exists) manifest['uses-permission'].push({$: {'android:name': name}});
}

function withComfortableHud(config) {
  config = withAndroidManifest(config, config => {
    const manifest = config.modResults.manifest;
    ensurePermission(manifest, 'android.permission.SYSTEM_ALERT_WINDOW');
    ensurePermission(manifest, 'android.permission.FOREGROUND_SERVICE');
    ensurePermission(manifest, 'android.permission.FOREGROUND_SERVICE_SPECIAL_USE');
    ensurePermission(manifest, 'android.permission.POST_NOTIFICATIONS');

    const application = manifest.application?.[0];
    if (!application) throw new Error('TornPulse: Android application manifest node not found.');
    application.service = application.service || [];
    const serviceName = `${PACKAGE_NAME}.ComfortableOverlayService`;
    const exists = application.service.some(service => {
      const name = service?.$?.['android:name'];
      return name === serviceName || name === '.ComfortableOverlayService';
    });
    if (!exists) {
      application.service.push({
        $: {
          'android:name': serviceName,
          'android:exported': 'false',
          'android:stopWithTask': 'false',
          'android:foregroundServiceType': 'specialUse',
        },
        property: [{
          $: {
            'android:name': 'android.app.PROPERTY_SPECIAL_USE_FGS_SUBTYPE',
            'android:value': 'Floating Torn status HUD for the user while other apps are open',
          },
        }],
      });
    }
    return config;
  });

  config = withMainApplication(config, config => {
    let source = config.modResults.contents;
    if (!source.includes('ComfortableOverlayPackage()')) {
      if (config.modResults.language === 'kt' || source.includes('PackageList(this).packages.apply {')) {
        const marker = 'PackageList(this).packages.apply {';
        if (!source.includes(marker)) throw new Error('TornPulse: could not find Kotlin package list in MainApplication.');
        source = source.replace(marker, `${marker}\n              add(ComfortableOverlayPackage())`);
      } else {
        const marker = 'List<ReactPackage> packages = new PackageList(this).getPackages();';
        if (!source.includes(marker)) throw new Error('TornPulse: could not find Java package list in MainApplication.');
        source = source.replace(marker, `${marker}\n        packages.add(new ComfortableOverlayPackage());`);
      }
    }
    config.modResults.contents = source;
    return config;
  });

  config = withDangerousMod(config, ['android', async config => {
    const root = config.modRequest.projectRoot;
    const srcDir = path.join(root, 'src');
    fs.mkdirSync(srcDir, {recursive: true});

    // Patch the JS app used by the release bundle after the workflow restores /src.
    const playDisclosure = APP_JS.replace(
      'Android needs “Display over other apps” permission so TornPulse can stay visible while Torn is open.',
      'TornPulse uses Display over other apps only when you start the floating HUD. It shows your Torn stats in a small right-edge rail while another app is visible. It does not read taps, control other apps, capture your screen, or show ads. You can stop the HUD in TornPulse and revoke access in Android settings at any time.'
    );
    fs.writeFileSync(path.join(root, 'App.js'), playDisclosure, 'utf8');
    fs.writeFileSync(path.join(root, 'core.js'), CORE_JS, 'utf8');
    fs.writeFileSync(path.join(root, 'tornApi.js'), TORN_API_JS, 'utf8');
    fs.writeFileSync(path.join(srcDir, 'core.js'), CORE_JS, 'utf8');
    fs.writeFileSync(path.join(srcDir, 'tornApi.js'), TORN_API_JS, 'utf8');

    const javaDir = path.join(root, 'android', 'app', 'src', 'main', 'java', ...PACKAGE_NAME.split('.'));
    fs.mkdirSync(javaDir, {recursive: true});
    const brandedNamespace = source => source.replaceAll('com.comfortableai.torncopilot', PACKAGE_NAME);
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayModule.kt'), brandedNamespace(OVERLAY_MODULE_KT), 'utf8');
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayPackage.kt'), brandedNamespace(OVERLAY_PACKAGE_KT), 'utf8');
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayService.kt'), brandedNamespace(OVERLAY_SERVICE_KT), 'utf8');
    return config;
  }]);

  return config;
}

function withPlayReleaseSigning(config) {
  return withAppBuildGradle(config, config => {
    const required = [
      'TORNPULSE_UPLOAD_STORE_FILE',
      'TORNPULSE_UPLOAD_STORE_PASSWORD',
      'TORNPULSE_UPLOAD_KEY_ALIAS',
      'TORNPULSE_UPLOAD_KEY_PASSWORD',
    ];
    const enabled = required.every(name => Boolean(process.env[name]));
    if (!enabled) return config;

    let source = config.modResults.contents;
    const signingMarker = 'signingConfigs {\n        debug {';
    if (!source.includes(signingMarker)) {
      throw new Error('TornPulse: Android signingConfigs block not found.');
    }
    source = source.replace(signingMarker, `signingConfigs {
        release {
            storeFile file(System.getenv("TORNPULSE_UPLOAD_STORE_FILE"))
            storePassword System.getenv("TORNPULSE_UPLOAD_STORE_PASSWORD")
            keyAlias System.getenv("TORNPULSE_UPLOAD_KEY_ALIAS")
            keyPassword System.getenv("TORNPULSE_UPLOAD_KEY_PASSWORD")
        }
        debug {`);
    source = source.replace('signingConfig signingConfigs.debug', 'signingConfig signingConfigs.release');
    config.modResults.contents = source;
    return config;
  });
}

module.exports = ({ config }) => {
  config = {...config};
  config.name = 'TornPulse';
  config.slug = 'tornpulse';
  config.version = '1.0.0';
  config.orientation = 'portrait';
  config.userInterfaceStyle = 'dark';
  // Official TornPulse TP pulse emblem. Explicit config overrides any stale
  // app.json/default icon retained by Expo or Android prebuild.
  config.icon = './tornpulse-app-icon-v2.png';
  config.splash = {
    ...(config.splash || {}),
    image: './tornpulse-app-icon-v2.png',
    resizeMode: 'contain',
    backgroundColor: '#050607',
  };
  config.android = {
    ...(config.android || {}),
    adaptiveIcon: {
      ...((config.android && config.android.adaptiveIcon) || {}),
      foregroundImage: './tornpulse-app-icon-v2.png',
      monochromeImage: './tornpulse-app-icon-v2.png',
      backgroundColor: '#050607',
    },
  };
  config.icon = './tornpulse-icon.png';
  config.splash = {
    image: './tornpulse-splash.png',
    resizeMode: 'cover',
    backgroundColor: '#050607',
  };
  config.android = {
    ...(config.android || {}),
    package: PACKAGE_NAME,
    versionCode: 23,
  };

  const plugins = Array.isArray(config.plugins) ? [...config.plugins] : [];
  const pluginName = entry => Array.isArray(entry) ? entry[0] : entry;
  if (!plugins.some(entry => pluginName(entry) === 'expo-notifications')) {
    plugins.push(['expo-notifications', {defaultChannel: 'torn-alerts'}]);
  }
  if (!plugins.some(entry => pluginName(entry) === 'expo-secure-store')) {
    plugins.push('expo-secure-store');
  }
  config.plugins = plugins;

  return withPlayReleaseSigning(withComfortableHud(config));
};
